#pragma once#include "../HcdScripto/Translator.h"#include <HcdVarTypes.h>struct SSavablePart{  union  {    tBool bValue;    tDigital32 iValue;    tAnalog32 fltValue;  };  eHcdVType vType;  tHcdVarSizeType_ vSize;};struct SCalcVar : ns_HcdTranslator::KVar, SSavablePart{  BYTE *pMem;  SCalcVar* pLocal;  void operator = ( KVar &thr )  {    *(KVar*)this = thr;    if( LocalValue==Type && !pMem )    {      pMem = (BYTE*)&iValue;      pLocal = this;    }    if( ConstInteger==Type )    {      iValue = atoi( szName );      vType = ehtDigital32;      vSize = sizeof(iValue);    }    else if( ConstFloat==Type )    {      fltValue = (float)atof( szName );      vType = ehtAnalog32;      vSize = sizeof(fltValue);    }    else if( ConstBoolTF==Type )    {      if( !strcmp(szName,"true") )        bValue = true;      else if( !strcmp(szName,"false") )        bValue = false;      else      {        ASSD(0);      }      vType = ehtBool;      vSize = sizeof(bValue);    }  }};class SCalcRes : public SCalcVar{public:  bool m_bAddrVar;  SCalcRes();  operator tAnalog32();  SCalcRes& operator = ( bool b );  SCalcRes& operator = ( const SCalcVar &thr );  SCalcRes& Assign( SCalcRes &thr );  bool Compare( SCalcRes &thr, ns_HcdTranslator::eToken_value cmd );  static SCalcRes Action( SCalcRes &thl, SCalcRes &thr, ns_HcdTranslator::eToken_value cmd );  eHcdVType GetVarType();  void SetVarType( eHcdVType t );  BYTE *GetMem();  tHcdVarSizeType_ GetSize();  void SetSize( tHcdVarSizeType_ s );private:  template<typename L, typename R>  bool Compare( L l, R r, ns_HcdTranslator::eToken_value cmd );  template<typename T>  static T ActionImpl( T l, T r, ns_HcdTranslator::eToken_value cmd );  template<>  static float ActionImpl<float>( float l, float r, ns_HcdTranslator::eToken_value cmd );};